const body = $input.first().json.body || {};
const sortMap = { '신상품순':'da', '최저가순':'aa', '인기순':'ha' };
return [{ json: {
  ca: body.category || '',
  kw: body.keyword || '',
  so: body.sort ? (sortMap[body.sort] || body.sort) : 'da',
  sz: String(body.size || 30),
  pg: String(body.page || 1)
} }];

const raw = $input.first().json.domeggook || {};
const header = raw.header || {};
const rawItems = (raw.list && raw.list.item) ? (Array.isArray(raw.list.item) ? raw.list.item : [raw.list.item]) : [];

const items = rawItems.map(it => ({
  itemNo: it.no,
  title: it.title,
  thumb: it.thumb,
  price: Number(it.price) || 0,
  unitQty: Number(it.unitQty) || 1,
  sellerId: it.id,
  deliFee: it.deli ? Number(it.deli.fee) || 0 : 0,
  url: it.url
}));

return [{ json: {
  items,
  total: Number(header.numberOfItems) || 0,
  currentPage: Number(header.currentPage) || 1,
  numberOfPages: Number(header.numberOfPages) || 1
} }];

const dg = $input.first().json.domeggook || {};
const b = dg.basis || {};
const q = dg.qty || {};
const d = dg.deli || {};
const s = dg.seller || {};
const det = dg.detail || {};
const desc = dg.desc || {};

let options = null;
if (dg.selectOpt) {
  try {
    const parsed = JSON.parse(dg.selectOpt);
    options = {
      type: parsed.type,
      groups: (parsed.set || []).map(g => ({
        name: g.name,
        choices: g.opts,
        extraPrice: g.domPrice
      })),
      combinations: Object.entries(parsed.data || {}).map(([key, v]) => ({
        key,
        name: v.name,
        price: Number(v.domPrice) || 0,
        qty: Number(v.qty) || 0,
        available: v.dom === '1'
      }))
    };
  } catch(e) {
    options = null;
  }
}

return [{ json: {
  itemNo: b.no,
  title: b.title,
  status: b.status,
  keywords: (b.keywords && b.keywords.kw) || [],
  price: dg.price ? Number(dg.price.dome) : null,
  moq: q.domeMoq ? Number(q.domeMoq) : null,
  inventory: q.inventory ? Number(q.inventory) : null,
  options,
  deliMethod: d.method,
  deliFee: d.dome ? Number(d.dome.fee) : null,
  deliType: d.dome ? d.dome.type : null,
  deliWaiting: d.wating,
  seller: {
    id: s.id,
    rank: s.rank,
    scoreAvg: s.score ? s.score.avg : null,
    companyName: s.company ? s.company.name : null,
    boss: s.company ? s.company.boss : null,
    cno: s.company ? s.company.cno : null,
    addr: s.company ? s.company.addr : null,
    phone: s.company ? s.company.phone : null
  },
  detail: {
    country: det.country,
    manufacturer: det.manufacturer,
    model: det.model,
    itemCustomCode: det.itemCustomCode
  },
  thumb: dg.thumb || {},
  descHtml: (desc.contents && desc.contents.item) || '',
  descImageLicenseUsable: desc.license ? (desc.license.usable === 'true') : null,
  domemeUrl: 'https://domeggook.com/' + b.no + '?market=dome'
} }];

const b = $input.first().json.body || {};
return [{ json: {
  itemNo: b.itemNo,
  title: b.title || '',
  category: b.category || '',
  status: b.status || '',
  thumb: b.thumb || '',
  decidedAt: b.status && b.status !== 'pending' ? new Date().toISOString() : '',
  updatedAt: new Date().toISOString()
} }];

const b = $input.first().json.body || {};
return [{ json: {
  platform: b.platform || '',
  itemNo: b.itemNo || '',
  title: b.title || '',
  uploadedAt: new Date().toISOString(),
  bizId: b.bizId || '',
  payload: b.payload || ''
} }];

const target = String($('WH SourcingDelete').first().json.body.itemNo);
const rows = $input.all();
const match = rows.find(r => String(r.json.itemNo) === target);
if(!match) return [];
return [{ json: { rowNumber: match.json.row_number } }];

const body = $('WH UploadDelete').first().json.body;
const platform = body.platform;
const rowNumber = body.rowNumber;
const rows = $input.all();
const match = rows.find(r => String(r.json.row_number) === String(rowNumber));
if(!match) return [];
return [{ json: { rowNumber: match.json.row_number } }];

